package com.gomgomapps.math.core;
import java.util.*;import org.junit.Test;import static org.junit.Assert.*;
public class NamibiaFractionQuantityTest {
 @Test public void officialExamplePublicCheckAndFiveBlankRelations(){Question q=QuantityFractionPictures.create(Catalog.get(QuantityFractionCheck.ID),2,3,5,"number");q.answers=new String[]{"999"};q.expression="999";assertArrayEquals(new int[]{15,2,3,5,10},QuantityFractionCheck.read(q));assertTrue(new Checker().check(q,List.of(),List.of("10")).correct());assertFalse(new Checker().check(q,List.of(),List.of("11")).correct());HelpPlan h=HelpPlan.forQuestion(q);assertEquals(5,h.size());assertFalse(h.canTransfer());int[] a={15,2,3,5,10};for(int i=0;i<5;i++){assertTrue(h.step(i).accepts(""+a[i]));assertFalse(h.step(i).accepts(""+(a[i]+1)));}assertFalse(FractionInput.defaultFraction(q));}
 @Test public void selectedNaSixMenuFreshConditionsAndWholeResult(){var pack=GlobalCurriculum.packs("NA").stream().filter(p->p.id.equals("na-nied-primary-2024-v1")).findFirst().orElseThrow();assertTrue(pack.inGrade(QuantityFractionCheck.ID,6));var limits=GlobalCurriculum.limits(pack.id,QuantityFractionCheck.ID,6);Generator g=new Generator(new Random(284));List<String> recent=new ArrayList<>();boolean nonUnit=false;for(int i=0;i<150;i++){Question q=g.next(QuantityFractionCheck.ID,recent,false,limits);assertFalse(recent.contains(q.signature()));recent.add(q.signature());int[] v=QuantityFractionCheck.read(q);assertNotNull(v);assertTrue(limits.allows(q));assertTrue(v[2]>=2&&v[2]<=12&&v[3]>=2&&v[3]<=12);nonUnit|=v[1]>1;assertTrue(new Checker().check(q,List.of(),List.of(""+v[4])).correct());assertFalse(HelpPlan.forQuestion(q).canTransfer());assertFalse(FractionInput.defaultFraction(q));}assertTrue(nonUnit);}
}
